<template><section class="manager"><header><div><h3><PosIcon name="pill" size="20" /> Generic Drug Substitution</h3><p>Search approved equivalents supplied by the pharmacy service.</p></div><div class="search"><input v-model="query" placeholder="Search medication or active ingredient" @keyup.enter="search" /><button @click="search"><PosIcon name="search" size="14" /> Search</button></div></header><p v-if="loading" class="state">Loading formulary…</p><p v-else-if="error" class="state error">{{ error }}</p><p v-else-if="!results.length" class="state">No approved substitutions are available.</p><div v-else class="results"><article v-for="drug in results" :key="drug.id"><div><strong>{{ drug.name }}</strong><span>{{ drug.generic_name || drug.category || 'Equivalent medication' }}</span></div><strong>KES {{ formatMoney(drug.price_minor) }}</strong><button @click="selectDrug(drug)">Add to sale</button></article></div></section></template>
<script setup>
import { onMounted, ref } from 'vue'
import { PosIcon } from '@pos/ui'
import { useApi } from '../../../../apps/pos/src/composables/useApi.js'
const emit = defineEmits(['add-item','notification']); const api = useApi(); const query = ref(''); const results = ref([]); const loading = ref(true); const error = ref('')
onMounted(search)
async function search(){ loading.value=true; try { const data=await api.get(`/api/v1/pharmacy/formulary${query.value ? `?q=${encodeURIComponent(query.value)}` : ''}`); results.value=data.items ?? [] } catch { error.value='The formulary could not be loaded. Please contact your administrator.' } finally { loading.value=false } }
function formatMoney(value){ return (Number(value||0)/100).toLocaleString() }
function selectDrug(drug){ const item={ id:drug.id,name:drug.name,sku:drug.sku,price_minor:Number(drug.price_minor),unit_price_minor:Number(drug.price_minor),quantity:1,kind:drug.kind||'stocked' }; emit('add-item',item); emit('notification',{message:'Medication added to the active sale',type:'success'}) }
</script>
<style scoped>.manager{display:flex;flex-direction:column;gap:16px}header{display:flex;justify-content:space-between;align-items:flex-start;gap:12px}h3{display:flex;align-items:center;gap:8px;margin:0;color:#1e293b}header p{margin:4px 0 0;color:#64748b;font-size:12px}.search{display:flex;gap:6px}.search input{min-width:220px;padding:8px;border:1px solid #cbd5e1;border-radius:6px}.search button,.results button{display:inline-flex;align-items:center;gap:5px;padding:8px 10px;border:0;border-radius:6px;background:#0284c7;color:#fff;font-size:11px;font-weight:700;cursor:pointer}.state{padding:24px;border:1px dashed #cbd5e1;border-radius:8px;color:#64748b;text-align:center;font-size:12px}.state.error{border-color:#fecaca;color:#b91c1c}.results{display:flex;flex-direction:column;gap:8px}.results article{display:flex;align-items:center;gap:12px;padding:12px;border:1px solid #e2e8f0;border-radius:8px}.results article div{flex:1}.results span{display:block;color:#64748b;font-size:11px}.results article>strong{color:#0284c7}@media(max-width:700px){header{flex-direction:column}.search{width:100%}.search input{min-width:0;flex:1}}</style>
